args.command:
# Check if hermes-gateway service info
systemctl cat hermes-gateway.service 2>/dev/null; echo "=== exit: $? ==="; echo ""; 
# Check snap mount units - any of them slowing things down?
systemctl list-units --type=mount | grep -c snap; echo "";
# Check if apt-daily timers fire at boot
systemctl list-timers apt-daily* --all 2>/dev/null; echo "";
# Check for recent package updates
grep " upgrade \| install " /var/log/apt/history.log 2>/dev/null | tail -5

# Check boot time breakdown from last boot
systemd-analyze time; echo "---"; 
# Check what user is seeing - any recent boot date comparisons
uptime -s; echo "---"; 
# Check if there was a recent kernel update
ls -lt /boot/vmlinuz-* | head -3
